// 1. Leer y parsear estado
const redisDataString = $input.first().json.estadoUsuarioTexto;
let estadoUsuario = {};
if (redisDataString) {
  try { estadoUsuario = JSON.parse(redisDataString); } catch (e) { estadoUsuario = {}; }
}

// 2. Variables MapeaDatos
const mapeaDatosOutput = $node["MapeaDatos"].json;

// --- LÓGICA DE ENRIQUECIMIENTO ---
let wsp_text = null; 

// 2.1 AUDIO (Whisper)
if (!wsp_text) {
    try {
        if ($node["Whisper Local (ASR)"] && $node["Whisper Local (ASR)"].json.data) {
            const tx = $node["Whisper Local (ASR)"].json.data.trim();
            if (tx.length > 0) wsp_text = `[SYSTEM NOTE: Nota de voz transcrita]: "${tx}"`;
        }
    } catch (e) {}
}

// 2.2 PDF (Nativo o Escaneado)
if (!wsp_text) {
    try {
        if ($node["Extraer de PDF"] && $node["Extraer de PDF"].json) {
            const title = ($node["Extraer de PDF"].json.info && $node["Extraer de PDF"].json.info.Title) || "Documento PDF";
            let content = "";
            let method = "";

            if ($node["Extraer de PDF"].json.text && $node["Extraer de PDF"].json.text.trim().length > 0) {
                content = $node["Extraer de PDF"].json.text;
                method = "digital";
            }
            else if ($node["Analyze image"] && $node["Analyze image"].json.content) {
                content = $node["Analyze image"].json.content;
                method = "OCR/Visión";
            }

            if (content.length > 0) {
                wsp_text = `[SYSTEM NOTE: PDF "${title}" (${method})]:\n\n"${content.substring(0, 20000)}"`;
            }
        }
    } catch (e) {}
}

// 2.3 IMAGEN (Directa)
if (!wsp_text) {
    try {
        if ($node["Analyze image"] && $node["Analyze image"].json.content) {
            wsp_text = `[SYSTEM NOTE: Imagen enviada. Descripción]: "${$node["Analyze image"].json.content}"`;
        }
    } catch (e) {}
}

// 2.4 TEXTO PLANO (.txt directo)
if (!wsp_text) {
    try {
        if ($node["Extraer de Texto (.txt)"] && $node["Extraer de Texto (.txt)"].json.data) {
            wsp_text = `[SYSTEM NOTE: Archivo de texto plano]:\n\n"${$node["Extraer de Texto (.txt)"].json.data.substring(0, 20000)}"`;
        }
    } catch (e) {}
}

// 2.5 ARCHIVO NO SOPORTADO (Detectado por Fallback) - ¡NUEVO!
// Si llegamos aquí y wsp_text sigue vacío, pero el binario existe, es un formato desconocido.
if (!wsp_text) {
    try {
        // Miramos si hay datos binarios en la entrada actual
        const binaryData = $input.first().binary; 

        // Verificamos si existe la propiedad 'data' (tu binario principal)
        if (binaryData && binaryData.data) {
            const fileName = binaryData.data.fileName || "archivo";
            const mimeType = binaryData.data.mimeType || "desconocido";

            // Creamos la nota de sistema informando del error de formato
            // Añadimos también el posible texto que el usuario haya escrito en el caption (mapeaDatosOutput.wsp_text)
            const userCaption = mapeaDatosOutput.wsp_text ? `\n\n(El usuario adjuntó este mensaje al archivo: "${mapeaDatosOutput.wsp_text}")` : "";

            wsp_text = `[SYSTEM NOTE: El usuario ha enviado un archivo llamado "${fileName}" (Tipo: ${mimeType}). \n⚠️ TU SISTEMA NO PUEDE LEER ESTE FORMATO. \nIndica amablemente al usuario que no puedes leer el contenido de archivos .${fileName.split('.').pop()} y pídele que te envíe el texto copiado o una captura de pantalla (imagen) o PDF.]${userCaption}`;
        }
    } catch (e) {}
}

// 2.6 TEXTO NORMAL (FALLBACK FINAL - Solo texto sin archivos)
if (!wsp_text) {
    wsp_text = mapeaDatosOutput.wsp_text || null;
}

// --- Resto de variables ---
const sessionId = mapeaDatosOutput.codeID || null;
const apikey = mapeaDatosOutput.apikey || null;
const server_url = mapeaDatosOutput.server_url || null;
const tlf = mapeaDatosOutput.tlf || null;
const name = mapeaDatosOutput.name || null;

const outputData = {
  isNewUser: Object.keys(estadoUsuario).length === 0,
  telefono: estadoUsuario.telefono || null,
  nombre: estadoUsuario.nombre || null,
  apellidos: estadoUsuario.apellidos || null,
  email: estadoUsuario.email || null,
  notas: estadoUsuario.notas || '',
  etiqueta_emocional: estadoUsuario.etiqueta_emocional || null,
  etiqueta_asunto: estadoUsuario.etiqueta_asunto || null,
  sessionId, apikey, server_url, wsp_text, tlf, name
};

return [{ json: outputData }];

