// Recuperamos los datos del Webhook usando .first() para asegurar que no falla por índices
const webhookData = $('Webhook').first().json.body;

// Verificamos que existan los datos
if (!webhookData || !webhookData.data) {
  throw new Error("¡No se encontró el objeto data en el Webhook!");
}

// Preparamos los datos limpios para el siguiente nodo
// CAMBIO IMPORTANTE: Enviamos 'webhookData.data' completo, no solo '.message'
return {
  json: {
    url: `${webhookData.server_url}/chat/getBase64FromMediaMessage/${webhookData.instance}`,
    apiKey: webhookData.apikey,
    payload: {
      message: webhookData.data, 
      convertToMp4: false
    }
  }
};

